func printDryRun(cmd *cobra.Command, opType string, vars map[string]any) error {
	fmt.Fprintf(os.Stderr, "[dry-run] Operation type: %s\n", opType)
	data, _ := json.MarshalIndent(vars, "", "  ")
	fmt.Fprintf(os.Stdout, "%s\n", data)
	return nil
}
